package com.vista.launcher;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;
public class MainActivity extends Activity {
 LinearLayout root,body,nav; String page="HOME",theme="Aurora"; Uri wallpaper; SharedPreferences prefs; ArrayList<A> apps=new ArrayList<>(); ArrayList<String> recent=new ArrayList<>(); int bg,accent,card;
 static class A {String name,pkg;Drawable icon;A(String n,String p,Drawable i){name=n;pkg=p;icon=i;}}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);prefs=getSharedPreferences("vista",0);theme=prefs.getString("theme","Aurora");String w=prefs.getString("wallpaper","");if(!w.isEmpty())wallpaper=Uri.parse(w);String r=prefs.getString("recent","");if(!r.isEmpty())recent.addAll(Arrays.asList(r.split("\\n")));scan();render();}
 void scan(){apps.clear();PackageManager pm=getPackageManager();Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LAUNCHER);for(ResolveInfo x:pm.queryIntentActivities(i,0)){String p=x.activityInfo.packageName;if(!p.equals(getPackageName())&&find(p)==null)apps.add(new A(x.loadLabel(pm).toString(),p,x.loadIcon(pm)));}Collections.sort(apps,(a,b)->a.name.compareToIgnoreCase(b.name));}
 A find(String p){for(A a:apps)if(a.pkg.equals(p))return a;return null;}
 void colors(){if(theme.equals("Arctic Blue")){bg=0xff09172b;accent=0xff5cbeff;card=0xff19314c;}else if(theme.equals("Glass Forest")){bg=0xff081e1b;accent=0xff5de6a4;card=0xff16362f;}else if(theme.equals("Dark")){bg=0xff0c0c0f;accent=0xffdddddd;card=0xff222227;}else{bg=0xff0c121d;accent=0xff2ddcb4;card=0xff1b2635;}}
 GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);return d;}
 TextView txt(String s,int size,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(c);t.setGravity(17);return t;}
 LinearLayout line(boolean vertical){LinearLayout l=new LinearLayout(this);l.setOrientation(vertical?1:0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 void render(){colors();root=line(true);root.setPadding(24,12,24,16);root.setBackgroundColor(bg);if(wallpaper!=null)try{Bitmap bm=android.provider.MediaStore.Images.Media.getBitmap(getContentResolver(),wallpaper);BitmapDrawable d=new BitmapDrawable(getResources(),bm);d.setAlpha(95);root.setBackground(d);}catch(Exception ignored){}setContentView(root);
 LinearLayout top=line(false);TextView logo=txt("✦  VISTA",25,accent);logo.setGravity(Gravity.CENTER_VERTICAL);top.addView(logo,new LinearLayout.LayoutParams(0,50,1));top.addView(txt(new java.text.SimpleDateFormat("EEE, d MMM • h:mm a",Locale.getDefault()).format(new Date()),15,-1));root.addView(top);
 nav=line(false);addNav("⌂ Home","HOME");addNav("▦ Apps","APPS");addNav("⚙ Settings","SETTINGS");root.addView(nav);
 ScrollView sc=new ScrollView(this);body=line(true);body.setPadding(0,8,0,16);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 if(page.equals("HOME"))home();else if(page.equals("APPS"))grid();else settings();}
 void addNav(String s,String p){TextView t=txt(s,17,page.equals(p)?accent:-1);t.setPadding(20,10,20,10);t.setBackground(shape(page.equals(p)?card:Color.TRANSPARENT,22));t.setFocusable(true);t.setOnClickListener(v->{page=p;render();});nav.addView(t);}
 void heading(String s){TextView t=txt(s,20,-1);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(0,15,0,8);t.setTypeface(null,1);body.addView(t);}
 void home(){LinearLayout hero=line(true);hero.setPadding(20,18,20,18);hero.setBackground(shape(0xff21394f,22));TextView g=txt("GOOD AFTERNOON",14,accent);g.setGravity(Gravity.LEFT);hero.addView(g);TextView title=txt("Your screen. Your style.",28,-1);title.setGravity(Gravity.LEFT);title.setTypeface(null,1);hero.addView(title);TextView wp=txt("＋ Choose your wallpaper",16,-1);wp.setGravity(Gravity.LEFT);hero.addView(wp);wp.setOnClickListener(v->pick());hero.setFocusable(true);wp.setFocusable(true);body.addView(hero);
 heading("★  Favorites");LinearLayout r=line(false);String[] names={"YouTube","Netflix","Prime Video","Plex","Spotify","Disney+"};int n=0;for(String s:names){for(A a:apps)if(a.name.toLowerCase().contains(s.toLowerCase())){r.addView(app(a,135));n++;break;}}if(n==0)for(int j=0;j<Math.min(5,apps.size());j++)r.addView(app(apps.get(j),135));HorizontalScrollView h=new HorizontalScrollView(this);h.setHorizontalScrollBarEnabled(false);h.addView(r);body.addView(h);
 heading("◷  Recently used");LinearLayout rr=line(false);for(String p:recent){A a=find(p);if(a!=null)rr.addView(app(a,135));}if(rr.getChildCount()==0)rr.addView(txt("Apps you open will appear here.",15,-1));HorizontalScrollView hh=new HorizontalScrollView(this);hh.addView(rr);body.addView(hh);
 heading("TV Quick Tools");LinearLayout tools=line(false);tools.addView(tool("All apps",()->{page="APPS";render();}));tools.addView(tool("Wallpaper",()->pick()));tools.addView(tool("Settings",()->{page="SETTINGS";render();}));body.addView(tools);}
 View app(A a,int width){LinearLayout c=line(true);c.setGravity(17);c.setPadding(8,8,8,8);c.setBackground(shape(card,16));c.setFocusable(true);ImageView im=new ImageView(this);im.setImageDrawable(a.icon);c.addView(im,new LinearLayout.LayoutParams(48,48));TextView nm=txt(a.name,13,-1);nm.setMaxLines(2);c.addView(nm);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(width,105);p.setMargins(0,0,10,0);c.setLayoutParams(p);c.setOnClickListener(v->launch(a));c.setOnFocusChangeListener((v,f)->c.setBackground(shape(f?accent:card,16)));return c;}
 View tool(String s,Runnable run){TextView t=txt(s,15,-1);t.setBackground(shape(card,15));t.setFocusable(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,58,1);p.setMargins(0,0,8,0);t.setLayoutParams(p);t.setOnClickListener(v->run.run());t.setOnFocusChangeListener((v,f)->t.setBackground(shape(f?accent:card,15)));return t;}
 void grid(){heading("All Apps • "+apps.size()+" installed");for(int i=0;i<apps.size();i+=4){LinearLayout r=line(false);for(int j=i;j<Math.min(i+4,apps.size());j++){View v=app(apps.get(j),140);v.setLayoutParams(new LinearLayout.LayoutParams(0,112,1));r.addView(v);}for(int j=Math.min(i+4,apps.size());j<i+4;j++)r.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));body.addView(r);}}
 void settings(){heading("Personalize Vista");addSetting("Choose background wallpaper","Use your own photo or image",()->pick());heading("Themes");for(String s:new String[]{"Aurora","Glass Forest","Arctic Blue","Dark"})addSetting((theme.equals(s)?"●  ":"○  ")+s,"Tap to apply theme",()->{theme=s;prefs.edit().putString("theme",s).apply();render();});heading("Launcher");addSetting("Refresh installed apps","Scan installed apps",()->{scan();page="APPS";render();});addSetting("Back to Home","Return to Vista",()->{page="HOME";render();});}
 void addSetting(String a,String b,Runnable action){TextView t=txt(a+"\n"+b,16,-1);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(16,12,16,12);t.setBackground(shape(card,14));t.setFocusable(true);t.setOnClickListener(v->action.run());t.setOnFocusChangeListener((v,f)->t.setBackground(shape(f?accent:card,14)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,8);t.setLayoutParams(p);body.addView(t);}
 void launch(A a){try{recent.remove(a.pkg);recent.add(0,a.pkg);while(recent.size()>8)recent.remove(recent.size()-1);StringBuilder s=new StringBuilder();for(String p:recent){if(s.length()>0)s.append("\n");s.append(p);}prefs.edit().putString("recent",s.toString()).apply();Intent i=getPackageManager().getLaunchIntentForPackage(a.pkg);if(i!=null)startActivity(i);}catch(Exception e){Toast.makeText(this,"Unable to launch app",0).show();}}
 void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");try{startActivityForResult(i,7);}catch(Exception e){i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("image/*");startActivityForResult(i,7);}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==7&&c==-1&&d!=null&&d.getData()!=null){wallpaper=d.getData();try{getContentResolver().takePersistableUriPermission(wallpaper,d.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}prefs.edit().putString("wallpaper",wallpaper.toString()).apply();render();}}
 public void onBackPressed(){if(!page.equals("HOME")){page="HOME";render();}else super.onBackPressed();}
}